export function historyFor(county: CaCounty): CountyHistory {
  const place = COUNTY_METRO[county];
  if (place) {
    return {
      rows: METRO_ROWS[place]!,
      stepMonths: 3,
      place: METRO_NAMES[place]!,
      spliceMonth: SPLICE[place] ?? null,
      anchorPrice: COUNTY_ANCHOR[county],
    };
  }
  return {
    rows: COUNTY_ROWS[county]!,
    stepMonths: 12,
    place: `${county} County`,
    spliceMonth: null,
    anchorPrice: COUNTY_ANCHOR[county],
  };
}

